import{_ as n,o as r,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const s="/assets/zaehlerstand-angleichen.DyEoA86p.png",t="/assets/einstellungen-startwerte.BMlVJq4b.png",d="/assets/zaehler-getauscht.DMhvSr40.png",b=JSON.parse('{"title":"Zählerstände korrigieren und Zähler tauschen","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/02.zaehlerstaende-korrigieren.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md","filePath":"de/adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md","lastUpdated":null}'),l={name:"de/adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md"};function h(u,e,o,c,g,m){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="zahlerstande-korrigieren-und-zahler-tauschen" tabindex="-1">Zählerstände korrigieren und Zähler tauschen <a class="header-anchor" href="#zahlerstande-korrigieren-und-zahler-tauschen" aria-label="Permalink to &quot;Zählerstände korrigieren und Zähler tauschen&quot;">​</a></h1><p><a id="correct-wrong-too-high-negative"></a></p><h2 id="wie-korrigiere-ich-falsche-zu-hohe-oder-negative-werte-nach-einem-reset" tabindex="-1">Wie korrigiere ich falsche, zu hohe oder negative Werte nach einem Reset? <a class="header-anchor" href="#wie-korrigiere-ich-falsche-zu-hohe-oder-negative-werte-nach-einem-reset" aria-label="Permalink to &quot;Wie korrigiere ich falsche, zu hohe oder negative Werte nach einem Reset?&quot;">​</a></h2><p>Mit der Aktion „Zählerstand angleichen“ bei der Quelle. Du gibst den Stand ein, den dein Zähler gerade zeigt, und SourceAnalytix passt den Gesamtstand sofort an, ohne Neustart.</p><ol><li>Öffne in den Instanz-Einstellungen im Tab „Übersicht“ die Quelle.</li><li>Wähle bei „Aktionen“ „Zählerstand angleichen“.</li><li>Trage bei „Was zeigt dein Zähler jetzt?“ den abgelesenen Stand ein.</li><li>Prüfe die Vorschau mit altem und neuem Gesamtstand und klicke auf „⚡ Angleichen“.</li></ol><p><img src="'+s+'" alt="Dialog „Zählerstand angleichen“ mit Vorschau"></p><p>Die Aktion verschiebt die Startwerte mit. Ein falscher Sprung, der schon im Verbrauch von heute oder diesem Monat steckt, bleibt deshalb stehen. Den entfernst du über die <a href="#values-negative-after-entering-start">Startwerte</a>.</p><h3 id="kosten-reparieren" tabindex="-1">Kosten reparieren <a class="header-anchor" href="#kosten-reparieren" aria-label="Permalink to &quot;Kosten reparieren&quot;">​</a></h3><p>Kosten werden mit jedem Wert gebucht, ein falscher Sprung steckt also auch in den Kosten. Wähle danach „Kosten ab Datum neu rechnen“ mit dem Tag, an dem der Fehler begann. SourceAnalytix rechnet die Kosten mit dem Preisverlauf neu, der Verbrauch bleibt gleich.</p><h3 id="gestern-und-altere-perioden" tabindex="-1">Gestern und ältere Perioden <a class="header-anchor" href="#gestern-und-altere-perioden" aria-label="Permalink to &quot;Gestern und ältere Perioden&quot;">​</a></h3><p>Abgeschlossene Perioden wie gestern, der Vormonat oder das Archiv unter <code>&lt;Jahr&gt;</code> rechnet das Angleichen nicht neu. Korrigierst du vor Mitternacht, bleibt der Fehler auf heute beschränkt. Ältere Werte und Werte in einer Historie wie InfluxDB änderst du von Hand.</p><p><strong>Siehe auch:</strong> <a href="#replaced-meter-device-avoid-negative">Zähler oder Gerät getauscht</a> · <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Vorperioden</a></p><p><a id="values-negative-after-entering-start"></a></p><h2 id="warum-sind-meine-werte-nach-der-eingabe-von-startwerten-negativ" tabindex="-1">Warum sind meine Werte nach der Eingabe von Startwerten negativ? <a class="header-anchor" href="#warum-sind-meine-werte-nach-der-eingabe-von-startwerten-negativ" aria-label="Permalink to &quot;Warum sind meine Werte nach der Eingabe von Startwerten negativ?&quot;">​</a></h2><p>Ein Startwert ist größer als der Gesamtstand. Der Verbrauch ist Gesamtstand minus Startwert und wird dann negativ. Die Einstellungsseite lässt solche Werte nicht mehr zu, sie entstehen aber durch alte Einträge oder Skripte.</p><table tabindex="0"><thead><tr><th>Eingetragen</th><th>Folge</th><th>Richtig</th></tr></thead><tbody><tr><td>Verbrauch der Periode statt Zählerstand</td><td>fast der ganze Zählerstand erscheint als Verbrauch</td><td>Stand zu Beginn der Periode</td></tr><tr><td>Stand in Wh, Preis rechnet in kWh</td><td>stark negativ</td><td>Wert in kWh</td></tr><tr><td>Wert des Geräts statt Gesamtstand</td><td>zu hoch oder negativ</td><td>„Gesamtstand“ der Quelle als Maßstab</td></tr><tr><td>„Monat“ oder „Jahr“ über „Tag“</td><td>die längere Periode wird negativ</td><td>„Tag“ ist der größte Startwert</td></tr></tbody></table><h3 id="so-korrigierst-du-die-startwerte" tabindex="-1">So korrigierst du die Startwerte <a class="header-anchor" href="#so-korrigierst-du-die-startwerte" aria-label="Permalink to &quot;So korrigierst du die Startwerte&quot;">​</a></h3><ol><li>Öffne die Quelle. Ganz oben steht der „Gesamtstand“.</li><li>Trage unter „Einstellungen“ › „Startwerte“ den Stand zu Beginn jeder Periode ein. Kennst du ihn nicht, leere das Feld; die Periode zählt dann ab jetzt.</li><li>Klicke auf „⚡ Übernehmen“. Passt ein Wert nicht, zeigt das Feld einen Fehler und die Schaltfläche bleibt gesperrt.</li></ol><p><img src="'+t+'" alt="Bereich „Einstellungen“ der Quelle mit „Startwerte“ und aufgeklapptem „Für Experten“"></p><p>Startwerte wirken nur bis zum nächsten Periodenwechsel. Stimmt der Gesamtstand selbst nicht, nimm <a href="#correct-wrong-too-high-negative">Zählerstand angleichen</a>.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#values-costs-far-too-high">Werte viel zu hoch oder negativ</a></p><p><a id="replaced-meter-device-avoid-negative"></a></p><h2 id="ich-habe-zahler-oder-gerat-getauscht-–-wie-vermeide-ich-negative-werte" tabindex="-1">Ich habe Zähler oder Gerät getauscht – wie vermeide ich negative Werte? <a class="header-anchor" href="#ich-habe-zahler-oder-gerat-getauscht-–-wie-vermeide-ich-negative-werte" aria-label="Permalink to &quot;Ich habe Zähler oder Gerät getauscht – wie vermeide ich negative Werte?&quot;">​</a></h2><p>Mit der Aktion „Zähler getauscht“, am besten bevor der neue Zähler den ersten Wert liefert. Beginnt der neue Zähler bei 0 und ist die Reset-Erkennung an, zählt SourceAnalytix auch ohne die Aktion weiter.</p><ol><li>Öffne die Quelle und wähle bei „Aktionen“ „Zähler getauscht“.</li><li>Trage den Endstand des alten Zählers, den Startstand des neuen und das Datum ein.</li><li>Prüfe die Vorschau und klicke auf „⚡ Tausch übernehmen“. Der Gesamtstand läuft vom alten Endstand weiter.</li></ol><p><img src="'+d+'" alt="Dialog „Zähler getauscht“ mit Endstand alt, Startstand neu und Datum"></p><p>Hat der neue Zähler schon Werte geliefert und ist der Gesamtstand gesprungen, nimm „Zählerstand angleichen“ und rechne die Kosten neu, siehe <a href="#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><h3 id="neues-gerat-mit-neuem-datenpunkt" tabindex="-1">Neues Gerät mit neuem Datenpunkt <a class="header-anchor" href="#neues-gerat-mit-neuem-datenpunkt" aria-label="Permalink to &quot;Neues Gerät mit neuem Datenpunkt&quot;">​</a></h3><p>Ein neuer Datenpunkt, etwa ein neuer Shelly, wäre eine neue Quelle. Das vermeidest du mit einem Alias: Aktiviere SourceAnalytix auf einem Alias (zum Beispiel unter <code>alias.0</code>) und stelle beim Tausch nur sein Ziel auf das neue Gerät um. Ordner und Gesamtstand bleiben.</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected“?</a> · <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">Name, Alias und Output-ID</a></p><p><a id="meter-restarts-after-power-loss"></a></p><h2 id="mein-zahler-startet-nach-stromausfall-oder-taglich-bei-0-–-was-stelle-ich-ein" tabindex="-1">Mein Zähler startet nach Stromausfall oder täglich bei 0 – was stelle ich ein? <a class="header-anchor" href="#mein-zahler-startet-nach-stromausfall-oder-taglich-bei-0-–-was-stelle-ich-ein" aria-label="Permalink to &quot;Mein Zähler startet nach Stromausfall oder täglich bei 0 – was stelle ich ein?&quot;">​</a></h2><p>Schalte die „Reset-Erkennung“ ein und stelle die Schwelle kleiner ein als den Betrag, um den der Zähler beim Neustart fällt. Dann zählt SourceAnalytix auf den alten Gesamtstand weiter. Bei Shelly und Tasmota schlägt der Assistent die Reset-Erkennung schon vor.</p><ol><li>Öffne die Quelle und setze unter „Einstellungen“ „Reset-Erkennung“.</li><li>Prüfe unter „Für Experten“ die „Schwelle Reset-Erkennung“. Sie steht in der Einheit der Preisdefinition. <ul><li>Zähler, der beim Stromausfall auf 0 fällt: Der Standard 1 passt.</li><li>Tageszähler: kleiner als dein kleinster Tagesverbrauch, zum Beispiel 0,1 kWh.</li><li>Kleine Einheiten wie m³: zum Beispiel 0,1 m³.</li></ul></li><li>Klicke auf „⚡ Übernehmen“.</li></ol><p><img src="'+t+'" alt="Bereich „Einstellungen“ mit „Reset-Erkennung“ und „Schwelle Reset-Erkennung“ unter „Für Experten“"></p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Fällt der Zähler um weniger als die Schwelle, gilt das als Messschwankung, und SourceAnalytix ignoriert neue Werte, bis sie den alten Stand übersteigen. Bei einem Tageszähler mit zu großer Schwelle fehlt so ein Teil des neuen Tages.</p></div><p>Springt eine Quelle ohne Reset-Erkennung auf 0, zeigt der Tab „Probleme“ „Zähler springt auf 0, Reset-Erkennung ist aus“ mit „⚡ Einschalten“. Gibt es neben dem Tageszähler einen Gesamtzähler, nimm lieber den.</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected“?</a> · <a href="./../referenz/einstellungen#threshold-disabling-reset-detection-work">Schwelle und Abschalten der Reset-Erkennung</a></p><p><a id="apply-real-meter-reading-cumulativereading"></a></p><h2 id="wie-ubernehme-ich-meinen-echten-zahlerstand-cumulativereading-raw-objekt" tabindex="-1">Wie übernehme ich meinen echten Zählerstand (cumulativeReading, RAW-Objekt)? <a class="header-anchor" href="#wie-ubernehme-ich-meinen-echten-zahlerstand-cumulativereading-raw-objekt" aria-label="Permalink to &quot;Wie übernehme ich meinen echten Zählerstand (cumulativeReading, RAW-Objekt)?&quot;">​</a></h2><p>Mit „Zählerstand angleichen“, wie unter <a href="#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> beschrieben. Ein Objekt musst du dafür nicht bearbeiten. Zeigt dein Gerät schon den echten Stand, etwa über einen Lesekopf, ist nichts zu tun.</p><p>Nur den State <code>cumulativeReading</code> zu ändern, hält nicht. Der Gesamtstand ist immer Gerätewert plus Offset, und der nächste Wert rechnet ihn neu. Die Aktion setzt beides passend zueinander.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Was ist cumulativeReading?</a> · <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Die Begriffe</a></p>',43)])])}const f=n(l,[["render",h]]);export{b as __pageData,f as default};
